SELECT id, full_name, email, job_title, hire_date, CUME_DIST() OVER (PARTITION BY level ORDER BY salary) AS salary_cume_dist, ROUND(salary / SUM(salary) OVER (PARTITION BY manager_id, dept_id), 4) AS salary_share, ROUND(salary / SUM(salary) OVER (PARTITION BY level), 4) AS salary_share_2, FIRST_VALUE(job_title) IGNORE NULLS OVER (PARTITION BY manager_id, dept_id ORDER BY hire_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_job_title, ROUND(salary / SUM(salary) OVER (PARTITION BY job_title), 4) AS salary_share_3 FROM employees;
